-- Seed curriculum topics Matematika SD Kelas 1-6
-- Sumber: CP_Per_Kelas_1.xlsx
-- Kolom Elemen dari Excel → kolom theme (tema) di database
-- Kolom Nomor → kolom topic di database
-- Kolom Deskripsi → kolom learning_outcomes di database

do $$
declare
  math_subject_id uuid;
begin
  -- Insert subject Matematika SD jika belum ada
  values ('Matematika', 'Matematika Sekolah Dasar', array['SD'])
  on conflict do nothing;

  select id into math_subject_id
  from subjects
  where name = 'Matematika' and 'SD' = any(level)
  limit 1;

  if math_subject_id is null then
    raise exception 'Subject Matematika SD tidak ditemukan setelah insert';
  end if;

  -- Hapus data lama untuk kelas 1-6 jika ada
  delete from curriculum_topics
  where subject_id = math_subject_id
    and grade_level in ('Kelas 1','Kelas 2','Kelas 3','Kelas 4','Kelas 5','Kelas 6');

  -- Insert 188 capaian pembelajaran
  ;
end $$;